package com.javacodingagent.api.trace;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import java.io.IOException; import java.util.*; import java.util.concurrent.*;
public class TaskEventBroker { private final Map<Long, List<SseEmitter>> subscribers = new ConcurrentHashMap<>(); public SseEmitter subscribe(long taskId) { var emitter = new SseEmitter(0L); subscribers.computeIfAbsent(taskId, ignored -> new CopyOnWriteArrayList<>()).add(emitter); emitter.onCompletion(() -> remove(taskId, emitter)); emitter.onTimeout(() -> remove(taskId, emitter)); return emitter; } public void publish(long taskId, String type, Object data) { for (SseEmitter emitter : subscribers.getOrDefault(taskId, List.of())) try { emitter.send(SseEmitter.event().name(type).data(data)); } catch (IOException e) { remove(taskId, emitter); } } private void remove(long id, SseEmitter emitter) { subscribers.getOrDefault(id, List.of()).remove(emitter); } }
